1	package br.com.loja.checkout;
2	
3	import br.com.loja.checkout.api.ItemRequest;
4	import br.com.loja.checkout.api.ResumoRequest;
5	import br.com.loja.checkout.api.ResumoResponse;
6	import br.com.loja.checkout.clube.NivelClube;
7	import br.com.loja.checkout.cupom.Cupom;
8	import br.com.loja.checkout.entrega.ModalidadeEntrega;
9	import br.com.loja.checkout.pagamento.Cobranca;
10	import br.com.loja.checkout.pagamento.FormaPagamento;
11	import java.math.BigDecimal;
12	import java.util.List;
13	import java.util.Objects;
14	import java.util.Optional;
15	import org.springframework.stereotype.Service;
16	
17	@Service
18	public class CheckoutService {
19	
20	    private final Catalogo<ModalidadeEntrega> modalidades;
21	    private final Catalogo<Cupom> cupons;
22	    private final Catalogo<NivelClube> niveis;
23	    private final Catalogo<FormaPagamento> formasPagamento;
24	
25	    public CheckoutService(List<ModalidadeEntrega> modalidades, List<Cupom> cupons,
26	            List<NivelClube> niveis, List<FormaPagamento> formasPagamento) {
27	        this.modalidades = new Catalogo<>(modalidades);
28	        this.cupons = new Catalogo<>(cupons);
29	        this.niveis = new Catalogo<>(niveis);
30	        this.formasPagamento = new Catalogo<>(formasPagamento);
31	    }
32	
33	    public ResumoResponse resumir(ResumoRequest pedido) {
34	        Carrinho carrinho = carrinho(pedido.itens());
35	        NivelClube nivel = exigir(niveis.buscar(pedido.nivelClube()), "NIVEL_CLUBE_INVALIDO");
36	        Regiao regiao = exigir(Regiao.de(pedido.regiao()), "REGIAO_INVALIDA");
37	
38	        ModalidadeEntrega modalidade = exigir(modalidades.buscar(pedido.modalidadeEntrega()), "MODALIDADE_INVALIDA");
39	        exigir(modalidade.atende(carrinho), "MODALIDADE_INDISPONIVEL");
40	
41	        Optional<Cupom> cupom = cupom(pedido.cupom(), carrinho);
42	
43	        FormaPagamento formaPagamento = exigir(formasPagamento.buscar(pedido.formaPagamento()), "FORMA_PAGAMENTO_INVALIDA");
44	        int parcelas = Objects.requireNonNullElse(pedido.parcelas(), 1);
45	        exigir(formaPagamento.aceitaParcelas(parcelas), "PARCELAMENTO_INVALIDO");
46	
47	        BigDecimal subtotal = carrinho.subtotal();
48	        BigDecimal frete = nivel.freteCobrado(modalidade.frete(carrinho));
49	        BigDecimal desconto = cupom.map(c -> c.desconto(carrinho, frete)).orElse(Dinheiro.ZERO);
50	        BigDecimal seguro = regiao.seguro(subtotal);
51	        BigDecimal totalPedido = subtotal.subtract(desconto).add(frete).add(seguro);
52	
53	        exigir(formaPagamento.atende(totalPedido), "FORMA_PAGAMENTO_INDISPONIVEL");
54	        Cobranca cobranca = formaPagamento.cobrar(totalPedido, parcelas);
55	
56	        return new ResumoResponse(
57	                subtotal,
58	                desconto,
59	                frete,
60	                modalidade.prazoDias(),
61	                seguro,
62	                cobranca.totalFinal().subtract(totalPedido),
63	                cobranca.totalFinal(),
64	                parcelas,
65	                cobranca.valorParcela(),
66	                nivel.creditoProximaCompra(subtotal),
67	                nivel.brinde(subtotal));
68	    }
69	
70	    private static Carrinho carrinho(List<ItemRequest> itens) {
71	        exigir(itens != null && !itens.isEmpty() && itens.stream().allMatch(CheckoutService::itemValido), "PEDIDO_INVALIDO");
72	        return new Carrinho(itens.stream()
73	                .map(i -> new Item(i.nome(), i.precoUnitario(), i.quantidade(), i.pesoKg()))
74	                .toList());
75	    }
76	
77	    private static boolean itemValido(ItemRequest item) {
78	        return item != null
79	                && positivo(item.precoUnitario())
80	                && item.quantidade() != null && item.quantidade() > 0
81	                && positivo(item.pesoKg());
82	    }
83	
84	    private static boolean positivo(BigDecimal valor) {
85	        return valor != null && valor.signum() > 0;
86	    }
87	
88	    private Optional<Cupom> cupom(String codigo, Carrinho carrinho) {
89	        if (codigo == null) {
90	            return Optional.empty();
91	        }
92	        Cupom cupom = exigir(cupons.buscar(codigo), "CUPOM_INVALIDO");
93	        exigir(cupom.aplicavel(carrinho), "CUPOM_NAO_APLICAVEL");
94	        return Optional.of(cupom);
95	    }
96	
97	    private static <T> T exigir(Optional<T> valor, String erro) {
98	        return valor.orElseThrow(() -> new PedidoRecusadoException(erro));
99	    }
100	
101	    private static void exigir(boolean condicao, String erro) {
102	        if (!condicao) {
103	            throw new PedidoRecusadoException(erro);
104	        }
105	    }
106	}
