5	
6	/** Arredondamento de valores em dinheiro: centavos, meio para o par. */
7	public final class Dinheiro {
8	
9	    public static final BigDecimal ZERO = centavos(BigDecimal.ZERO);
10	
11	    private Dinheiro() {
12	    }
13	
14	    public static BigDecimal centavos(BigDecimal valor) {
15	        return valor.setScale(2, RoundingMode.HALF_EVEN);
16	    }
17	
18	    public static BigDecimal porcentagem(BigDecimal valor, String percentual) {
19	        return centavos(valor.multiply(new BigDecimal(percentual)).movePointLeft(2));
20	    }
21	}
