1	package br.com.loja.checkout.pagamento;
2	
3	import br.com.loja.checkout.Dinheiro;
4	import java.math.BigDecimal;
5	import java.math.MathContext;
6	import java.math.RoundingMode;
7	import org.springframework.stereotype.Component;
8	
9	@Component
10	class Cartao implements FormaPagamento {
11	
12	    private static final int MAXIMO_PARCELAS = 12;
13	    private static final int MAXIMO_SEM_JUROS = 3;
14	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
15	
16	    @Override
17	    public String codigo() {
18	        return "CARTAO";
19	    }
20	
21	    @Override
22	    public boolean aceitaParcelas(int parcelas) {
23	        return parcelas >= 1 && parcelas <= MAXIMO_PARCELAS;
24	    }
25	
26	    @Override
27	    public Cobranca cobrar(BigDecimal totalPedido, int parcelas) {
28	        if (parcelas <= MAXIMO_SEM_JUROS) {
29	            return new Cobranca(totalPedido, totalPedido.divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN));
30	        }
31	        BigDecimal parcela = parcelaPrice(totalPedido, parcelas);
32	        return new Cobranca(parcela.multiply(BigDecimal.valueOf(parcelas)), parcela);
33	    }
34	
35	    /** Tabela Price: total × taxa ÷ (1 − (1 + taxa)^−n). */
36	    private static BigDecimal parcelaPrice(BigDecimal total, int parcelas) {
37	        MathContext mc = MathContext.DECIMAL128;
38	        BigDecimal descontoComposto = BigDecimal.ONE.divide(BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas, mc), mc);
